// ── D57 / D58 · A GENERATED RÉSUMÉ IS ATTACHED TO ITS JOB — stored once, found everywhere ─────────
//
// Owner, 10-07: a résumé generated by hand "couldn't be found when I went back, across all panels",
// and the job's score stayed on the base résumé's. Measured on a throwaway server (synthetic user,
// a no-model tools stub), the write was there — `resumes` + `resume_versions`, the slot debited once —
// but it was dropped at three seams, and this module is where those seams are closed:
//
//   1. ⛔ A REGENERATION AFTER AN EXPORT NEVER REACHED `resumes`. Exporting a PDF marks that version
//      kept (/api/resumes/:jobId/keep), and coreGenerateResume wrote `resumes` only `if (!keptExists)`.
//      So the next generation — charged a Draft slot, shown once in the sandbox — lived only in
//      resume_versions: after a reload the board, the posting panel, The Table, the ATS card and the
//      application's score at apply all read the OLD résumé and its OLD score (walk: v1 19 kept,
//      v2 15 generated, `resumes.ats_score` still 19). The newest generation IS the résumé that would
//      be sent, so it is now always the one in `resumes`; "kept" stays a fact about the version the
//      user exported (resume_versions.is_kept), not a lock on what is current.
//   2. The three writes were three statements. A failure between them left a version with no
//      `resumes` row (or the reverse). They are one transaction now — both or neither.
//   3. A failure to store said nothing and kept the plan's generation count: the usage row
//      (usage_events, success=1 — what limitEnforcer counts) is written when the tools service
//      answers, BEFORE the store. A store that fails now REFUNDS that count (the row is kept as spend,
//      marked success=0 with the reason) and the route says so; the Draft slot is debited only after a
//      stored résumé, so it was never taken.
//
// ⭐ D57 · RETENTION. A résumé not tied to an application is a CONVENIENCE COPY, not evidence: kept for
// RESUME_RETENTION_DAYS (default 90 — A57's rule; owner may change it) from its latest generation, and
// shown with "expires in N days". Once the job is DRAFTED or APPLIED it is kept for good — the tie is
// read when the sweep runs, so a résumé an application points at is never swept.

export const DEFAULT_RESUME_RETENTION_DAYS = 90;

export function resumeRetentionDays(env = process.env) {
  const n = Number(env?.RESUME_RETENTION_DAYS);
  return Number.isFinite(n) && n > 0 ? Math.floor(n) : DEFAULT_RESUME_RETENTION_DAYS;
}

export class ResumeStoreError extends Error {
  constructor(message, { cause = null, refunded = false } = {}) {
    super(message);
    this.name = "ResumeStoreError";
    this.code = "resume_store_failed";
    this.retryable = true;
    this.permanent = false;
    this.refunded = refunded;
    this.cause = cause;
  }
}

/** The sentence the user reads when a generation could not be stored. Never "something went wrong". */
export const STORE_FAILED_SENTENCE =
  "Your résumé was written but could not be saved, so it was not charged — no draft was used. Try again.";

/**
 * Writes a NEW generation: the version, the job's current résumé, and the user_jobs flag — one
 * transaction. Returns { version, resumeId }. Throws whatever the database threw; the caller refunds.
 */
export function storeGeneratedResume(db, {
  userId, jobId, job = {}, tool = "generate", mode = "TAILORED", html, atsScore = null, atsReport = null,
  atsCacheKey = null, promptVersion = null, domainProfileId = null, userJobProfileId = null,
}) {
  const id = String(jobId);
  const report = atsReport == null ? null : (typeof atsReport === "string" ? atsReport : JSON.stringify(atsReport));
  return db.transaction(() => {
    const version = (db.prepare("SELECT MAX(version) AS v FROM resume_versions WHERE user_id=? AND job_id=?")
      .get(userId, id)?.v || 0) + 1;
    db.prepare(`INSERT INTO resume_versions (user_id,job_id,company,role,category,html,ats_score,ats_report,tool_type,is_kept,version,ats_cache_key,ats_prompt_version)
      VALUES (?,?,?,?,?,?,?,?,?,0,?,?,?)`)
      .run(userId, id, job.company ?? null, job.title ?? null, job.category ?? null, html, atsScore, report, tool, version,
           atsCacheKey, promptVersion);
    // ⛔ ALWAYS — the newest generation is the résumé that would be sent (see 1 above). AH5: the
    // profile is STAMPED so the reuse rule can ask whether it was built for the active one.
    db.prepare(`INSERT INTO resumes (user_id,job_id,company,role,category,apply_mode,html,ats_score,ats_report,ats_cache_key,ats_prompt_version,domain_profile_id,created_at,updated_at)
      VALUES (?,?,?,?,?,?,?,?,?,?,?,?,unixepoch(),unixepoch())
      ON CONFLICT(user_id,job_id) DO UPDATE SET html=excluded.html,role=excluded.role,category=excluded.category,
      apply_mode=excluded.apply_mode,ats_score=excluded.ats_score,ats_report=excluded.ats_report,
      ats_cache_key=excluded.ats_cache_key,ats_prompt_version=excluded.ats_prompt_version,
      domain_profile_id=excluded.domain_profile_id,updated_at=excluded.updated_at`)
      .run(userId, id, job.company ?? null, job.title ?? null, job.category ?? null, mode, html, atsScore, report,
           atsCacheKey, promptVersion, domainProfileId);
    // The job is the user's own once they generated for it — on the profile that generated it. A job
    // found by search outside the profile's role scope used to get NO user_jobs row at all (the profile
    // resolver answers null for an unmapped job), so resume_generated was never set for it.
    const ujProfile = userJobProfileId ?? domainProfileId;
    if (ujProfile != null) {
      db.prepare(`
        INSERT INTO user_jobs (user_id, job_id, domain_profile_id, resume_generated, updated_at)
        VALUES (?, ?, ?, 1, unixepoch())
        ON CONFLICT(user_id, job_id) DO UPDATE SET resume_generated = 1, updated_at = unixepoch()
      `).run(userId, id, ujProfile);
    }
    const resumeId = db.prepare("SELECT id FROM resumes WHERE user_id=? AND job_id=?").pluck().get(userId, id) ?? null;
    return { version, resumeId };
  })();
}

/**
 * Gives the plan's generation count back for a generation that produced nothing the user can reach.
 * The usage row stays (it is spend), marked unsuccessful with the reason, so limitEnforcer — which
 * counts success = 1 — no longer counts it. Returns whether a row was refunded. Never throws.
 */
export function refundGeneration(db, usageEventId, reason = "résumé not stored — refunded") {
  if (usageEventId == null) return false;
  try {
    return db.prepare("UPDATE usage_events SET success = 0, error_text = ? WHERE id = ? AND success = 1")
      .run(String(reason).slice(0, 200), usageEventId).changes > 0;
  } catch { return false; }
}

/** 'applied' | 'drafted' | null — what keeps a résumé for good. */
export function resumeTie(db, userId, jobId) {
  const one = (sql) => { try { return !!db.prepare(sql).get(userId, String(jobId)); } catch { return false; } };
  if (one("SELECT 1 FROM job_applications WHERE user_id=? AND job_id=?")
      || one("SELECT 1 FROM application_records WHERE user_id=? AND job_id=? AND state IN ('recorded','verified')")) return "applied";
  if (one("SELECT 1 FROM apply_run_jobs WHERE user_id=? AND job_id=? AND status <> 'cancelled'")) return "drafted";
  return null;
}

const DAY = 86400;

/** When this résumé was last generated (seconds): its newest version, else the row itself. */
const GENERATED_AT_SQL = `COALESCE((SELECT MAX(v.created_at) FROM resume_versions v WHERE v.user_id = r.user_id AND v.job_id = r.job_id),
                                   r.created_at, r.updated_at)`;

/**
 * Every generated résumé the user has, newest first — Settings → Your data → Generated résumés.
 * { jobId, company, role, atsScore, generatedAt (ms), versions, tie, keptForGood,
 *   expiresAt (ms|null), expiresInDays (int|null) }
 */
export function listGeneratedResumes(db, userId, { now = Math.floor(Date.now() / 1000), days = resumeRetentionDays() } = {}) {
  const rows = db.prepare(`
    SELECT r.job_id, r.company, r.role, r.ats_score, ${GENERATED_AT_SQL} AS generated_at,
           (SELECT COUNT(*) FROM resume_versions v WHERE v.user_id = r.user_id AND v.job_id = r.job_id) AS versions
    FROM resumes r WHERE r.user_id = ? AND r.html IS NOT NULL
    ORDER BY generated_at DESC
  `).all(userId);
  return rows.map(r => {
    const tie = resumeTie(db, userId, r.job_id);
    const expires = tie ? null : Number(r.generated_at) + days * DAY;
    return {
      jobId: r.job_id, company: r.company, role: r.role,
      atsScore: r.ats_score ?? null,
      generatedAt: r.generated_at ? Number(r.generated_at) * 1000 : null,
      versions: r.versions || 0,
      tie, keptForGood: !!tie,
      expiresAt: expires == null ? null : expires * 1000,
      expiresInDays: expires == null ? null : Math.max(0, Math.ceil((expires - now) / DAY)),
    };
  });
}

/** Deletes one job's résumé and its versions. Returns whether anything was removed. */
export function deleteGeneratedResume(db, userId, jobId) {
  return db.transaction(() => {
    const a = db.prepare("DELETE FROM resumes WHERE user_id=? AND job_id=?").run(userId, String(jobId)).changes;
    const b = db.prepare("DELETE FROM resume_versions WHERE user_id=? AND job_id=?").run(userId, String(jobId)).changes;
    // The job is no longer "a job I generated for" — the flag the board's own-rows and /d read.
    try { db.prepare("UPDATE user_jobs SET resume_generated = 0, updated_at = unixepoch() WHERE user_id=? AND job_id=?").run(userId, String(jobId)); }
    catch { /* a fixture without user_jobs */ }
    return a + b > 0;
  })();
}

/**
 * The retention sweep: deletes convenience copies older than `days` whose job is neither drafted nor
 * applied. Returns { swept: [{ userId, jobId }] }. A tied résumé is never touched.
 */
export const SWEEP_FLOOR = 20;          // a pass this small is never refused
export function sweepExpiredResumes(db, { now = Math.floor(Date.now() / 1000), days = resumeRetentionDays() } = {}) {
  const cutoff = now - days * DAY;
  const total = db.prepare("SELECT COUNT(*) FROM resumes").pluck().get();
  const due = db.prepare(`SELECT r.user_id, r.job_id FROM resumes r WHERE ${GENERATED_AT_SQL} < ?`).all(cutoff)
    .filter(c => !resumeTie(db, c.user_id, c.job_id));
  // ⛔ The bin's refusal shape (D53, and cleanup_log 85 before it): a sweep that would delete most of
  // what exists is a clock or a data problem until a person says otherwise.
  if (due.length > SWEEP_FLOOR && due.length > total / 2) return { swept: [], refused: true, due: due.length, total, cutoff, days };
  const swept = [];
  for (const c of due) {
    if (deleteGeneratedResume(db, c.user_id, c.job_id)) swept.push({ userId: c.user_id, jobId: c.job_id });
  }
  return { swept, refused: false, due: due.length, total, cutoff, days };
}
